// A adapter une seule fois : ID du document Grist.
// L'annonce Discord automatique (Mythique/Legendaire/Epique) et le partage
// manuel vivent desormais dans notify-reveal.json, declenches par le FRONT
// une fois le reveal termine (jamais ici, au tirage - ca spoilerait le
// joueur, voir opening.js onAllRevealed).
const adminDiscordIds = ['785223211730075709', '184008667690041345'];
const body = $input.first().json.body || {};
const requestedDryRun = !!body.dryRun;
const isAdmin = adminDiscordIds.includes((body.discordId || '').toString());
return [{
  json: {
    docId: 'cRP1WgZQv7KmwmVrUbuEF8',
    userId: Number(body.userId),
    extensionId: Number(body.extensionId),
    boosterSize: 5,
    dryRun: requestedDryRun && isAdmin
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const config = $('Set Config').first().json;
const userRows = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const user = userRows.find((u) => u.id === config.userId);
if (!user) {
  throw new Error('Utilisateur introuvable (userId=' + config.userId + ')');
}

const invRows = $('Get Booster Inventory').all().map((i) => i.json).filter((r) => r.id != null);
const inv = invRows.find((r) => refId(r.User) === config.userId && refId(r.Extension) === config.extensionId);

const boosterCount = user.BoosterCount || 0;

return [{
  json: {
    userId: config.userId,
    extensionId: config.extensionId,
    inventoryId: inv ? inv.id : null,
    inventoryExists: !!inv,
    boosterCount,
    hasStock: config.dryRun || boosterCount >= 1,
    pullsSinceTop: inv ? (inv.PullsSinceTopRarity || 0) : 0,
    totalPulls: user.TotalPulls || 0,
    xp: user.XP || 0
  }
}];

// Grist encode les colonnes de type liste (Attachments, RefList) sous la
// forme ["L", id1, id2, ...] : "L" est un marqueur, pas une valeur.
function refId(v) { return Array.isArray(v) ? v[1] : v; }
function firstAttachment(v) {
  if (!Array.isArray(v) || !v.length) return null;
  const ids = v[0] === 'L' ? v.slice(1) : v;
  return ids.length ? ids[0] : null;
}

const config = $('Set Config').first().json;
const status = $('Compute Booster Status').first().json;
let pullsSinceTop = status.pullsSinceTop;
let totalPulls = status.totalPulls;

const raritiesRows = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const cardsRows = $('Get Cards').all().map((i) => i.json).filter((c) => c.id != null && c.Active && refId(c.Extension) === config.extensionId && !c.IsPromo);
const configRows = $('Get Config Table').all().map((i) => i.json).filter((r) => r.id != null);
const allPulls = $('Get All Pulls').all().map((i) => i.json).filter((r) => r.id != null);
const finishRows = $('Get Finishes').all().map((i) => i.json).filter((r) => r.id != null);
const qualityRows = $('Get Qualities').all().map((i) => i.json).filter((r) => r.id != null);

if (!cardsRows.length) {
  throw new Error('Aucune carte tirable pour cette extension (verifie Active/Extension/IsPromo dans Grist)');
}

// Numeros d'exemplaire 'dans la nature' par carte : on suit precisement
// QUELS numeros sont utilises (pas juste un compteur) pour que le numero
// d'un exemplaire decrafte/defausse redevienne reellement disponible pour
// un futur tirage. Plus de quota (Cards.MaxSerial) : une carte reste
// tirable indefiniment, seule la REUTILISATION d'un numero deja en
// circulation est interdite - un numero libere par un decraft peut etre
// reattribue, mais aucun plafond global n'existe plus.
const usedSerialsByCard = {};
allPulls.forEach((p) => {
  const cid = refId(p.Card);
  if (!usedSerialsByCard[cid]) usedSerialsByCard[cid] = new Set();
  if (p.SerialNumber != null) usedSerialsByCard[cid].add(p.SerialNumber);
});
function usedCount(cardId) { return usedSerialsByCard[cardId] ? usedSerialsByCard[cardId].size : 0; }
function nextSerial(cardId) {
  const used = usedSerialsByCard[cardId];
  for (let n = 1; ; n++) {
    if (!used || !used.has(n)) return n;
  }
}
function markSerialUsed(cardId, serial) {
  if (!usedSerialsByCard[cardId]) usedSerialsByCard[cardId] = new Set();
  usedSerialsByCard[cardId].add(serial);
}

const availableCardsRows = cardsRows;

const cardsByRarity = {};
for (const c of availableCardsRows) {
  const rId = refId(c.Rarity);
  if (!cardsByRarity[rId]) cardsByRarity[rId] = [];
  cardsByRarity[rId].push(c);
}

let pityThreshold = Infinity;
let topRarityId = null;
if (configRows.length) {
  pityThreshold = configRows[0].PityThreshold || Infinity;
  topRarityId = refId(configRows[0].TopRarity);
}

// Deuxieme tirage independant du tirage de rarete : la carte piochee a
// une chance d'avoir une finition speciale (holo/gold/ghost/diamond/
// rainbow) plutot que 'normal'. 90% de rester normale, les 10% restants se
// repartissent entre les finitions selon Finishes.DropWeight (holo la plus
// commune, rainbow la plus rare - coherent avec l'echelle de fusion de
// craft.js/foil-upgrade.json).
// Reglables dans l'admin (Reglages avances > Boosters) ; vide ou 0 = defaut.
const cfgNum = (k, def) => (configRows.length && Number(configRows[0][k]) > 0 ? Number(configRows[0][k]) : def);
const SPECIAL_FINISH_CHANCE = cfgNum('SpecialFinishChance', 0.10);
const specialFinishes = finishRows.filter((f) => f.Key !== 'normal' && (f.DropWeight || 0) > 0);
const specialWeightTotal = specialFinishes.reduce((s, f) => s + (f.DropWeight || 0), 0);
function rollFinish() {
  if (!specialFinishes.length || Math.random() >= SPECIAL_FINISH_CHANCE) return 'normal';
  let roll = Math.random() * specialWeightTotal;
  for (const f of specialFinishes) {
    roll -= (f.DropWeight || 0);
    if (roll <= 0) return f.Key;
  }
  return specialFinishes[specialFinishes.length - 1].Key;
}

// Meme principe que rollFinish(), sur l'echelle de Qualite : 90% de sortir
// 'damaged' (comme toujours), les 10% restants se repartissent entre
// worn/good/mint selon Qualities.DropWeight (worn la plus commune, mint la
// plus rare) - un petit coup de chance possible des l'ouverture, en plus de
// la restauration par fusion de doublons.
const weightedQualities = qualityRows.filter((q) => (q.DropWeight || 0) > 0);
const qualityWeightTotal = weightedQualities.reduce((s, q) => s + (q.DropWeight || 0), 0);
function rollQuality() {
  // Tirage a un seul niveau sur les 4 paliers (voir Qualities.DropWeight) :
  // 'bon etat' est le palier de reference (le plus gros poids par defaut),
  // avec une chance de mieux tomber ('parfait etat') ou moins de chance
  // ('use'/'abime') - contrairement aux Finitions, il n'y a pas de palier
  // fixe a 90%, tout depend des poids configures dans Grist/l'admin.
  if (!weightedQualities.length) return 'good';
  let roll = Math.random() * qualityWeightTotal;
  for (const q of weightedQualities) {
    roll -= (q.DropWeight || 0);
    if (roll <= 0) return q.Key;
  }
  return weightedQualities[weightedQualities.length - 1].Key;
}

function weightedPick() {
  const total = raritiesRows.reduce((s, r) => s + (r.Weight || 0), 0);
  let roll = Math.random() * total;
  for (const r of raritiesRows) {
    roll -= (r.Weight || 0);
    if (roll <= 0) return r;
  }
  return raritiesRows[raritiesRows.length - 1];
}

// Raretes de booster (2026-10-02) :
// - 0.1% de booster SHINY : jamais de commune, finition speciale bien plus
//   frequente, etat tire deux fois (on garde le meilleur), et toujours une
//   carte bonus ;
// - 10% de chance d'une carte BONUS dans un booster normal.
const SHINY_CHANCE = cfgNum('ShinyPackChance', 0.001);
const BONUS_CARD_CHANCE = cfgNum('BonusCardChance', 0.10);
const isShiny = Math.random() < SHINY_CHANCE;
const hasBonusCard = isShiny || Math.random() < BONUS_CARD_CHANCE;
const cardCount = config.boosterSize + (hasBonusCard ? 1 : 0);
const lowestRarity = [...raritiesRows].sort((a, b) => (a.SortOrder || 0) - (b.SortOrder || 0))[0];
const QUALITY_RANK = ['damaged', 'worn', 'good', 'mint'];
function shinyPick() {
  const pool = raritiesRows.filter((r) => !lowestRarity || r.id !== lowestRarity.id);
  const total = pool.reduce((s, r) => s + (r.Weight || 0), 0);
  let roll = Math.random() * total;
  for (const r of pool) { roll -= (r.Weight || 0); if (roll <= 0) return r; }
  return pool[pool.length - 1] || weightedPick();
}
function shinyFinish() {
  if (!specialFinishes.length || Math.random() >= 0.5) return rollFinish();
  let roll = Math.random() * specialWeightTotal;
  for (const f of specialFinishes) { roll -= (f.DropWeight || 0); if (roll <= 0) return f.Key; }
  return specialFinishes[specialFinishes.length - 1].Key;
}
function shinyQuality() {
  const a = rollQuality(), b = rollQuality();
  return QUALITY_RANK.indexOf(a) >= QUALITY_RANK.indexOf(b) ? a : b;
}

const batchId = `${config.userId}-${Date.now()}`;
const nowEpoch = Math.floor(Date.now() / 1000);
const drawn = [];

for (let i = 0; i < cardCount; i++) {
  pullsSinceTop++;
  let rarity;
  if (pullsSinceTop >= pityThreshold && topRarityId) {
    rarity = raritiesRows.find((r) => r.id === topRarityId) || weightedPick();
  } else {
    rarity = isShiny ? shinyPick() : weightedPick();
  }
  if (rarity.id === topRarityId) pullsSinceTop = 0;

  // Cartes de la rarete tiree qui ne sont pas epuisees ; a defaut, n'importe
  // quelle carte encore disponible de l'extension (pool de secours).
  const pool = (cardsByRarity[rarity.id] && cardsByRarity[rarity.id].length) ? cardsByRarity[rarity.id] : availableCardsRows;
  if (!pool.length) {
    throw new Error('Plus aucune carte disponible dans cette extension pendant le tirage.');
  }
  const card = pool[Math.floor(Math.random() * pool.length)];
  // La carte piochee peut venir du pool de secours (aucune carte pour la
  // rarete tiree dans cette extension) : on affiche toujours la VRAIE
  // rarete de la carte, jamais la rarete tiree.
  const cardRarity = raritiesRows.find((r) => r.id === refId(card.Rarity)) || rarity;

  const serialNumber = nextSerial(card.id);
  markSerialUsed(card.id, serialNumber);

  drawn.push({
    isFirstEver: !card.FirstObtainedBy,
    userId: config.userId,
    extensionId: config.extensionId,
    inventoryId: status.inventoryId,
    inventoryExists: status.inventoryExists,
    cardId: card.id,
    obtainedAt: nowEpoch,
    batchId,
    name: card.Name,
    artist: card.Artist,
    description: card.Description,
    imageId: firstAttachment(card.Image),
    rarity: { id: cardRarity.id, name: cardRarity.Name, key: cardRarity.Key, colorHex: cardRarity.ColorHex, sortOrder: cardRarity.SortOrder || 0 },
    serialNumber,
    finish: isShiny ? shinyFinish() : rollFinish(),
    quality: isShiny ? shinyQuality() : rollQuality(),
    isShinyPack: isShiny,
    isBonusCard: hasBonusCard && i === cardCount - 1
  });
}

totalPulls += cardCount;
// Revelees de la moins rare a la plus rare : la meilleure carte arrive en dernier.
drawn.sort((a, b) => (a.rarity.sortOrder - b.rarity.sortOrder));

// Niveaux de profil : XP gagnee en ouvrant un booster, +1 booster bonus par
// niveau franchi (peut en franchir plusieurs d'un coup si un gros lot d'XP
// venait a etre accorde ailleurs).
function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const XP_PER_BOOSTER_OPEN = cfgNum('XpPerBoosterOpen', 10);
const newXp = (status.xp || 0) + XP_PER_BOOSTER_OPEN;
const levelsGained = levelForXp(newXp) - levelForXp(status.xp || 0);
const newBoosterCount = status.boosterCount - 1 + levelsGained;

return drawn.map((d) => ({ json: { ...d, pullsSinceTop, totalPulls, newBoosterCount, newXp, levelsGained } }));

function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const cards = $('Draw Cards').all().map((i) => ({
  cardId: i.json.cardId,
  name: i.json.name,
  artist: i.json.artist,
  description: i.json.description,
  imageId: i.json.imageId,
  rarity: i.json.rarity,
  isFirstEver: !!i.json.isFirstEver,
  serialNumber: i.json.serialNumber,
  finish: i.json.finish || 'normal',
  quality: i.json.quality || 'damaged',
  isBonusCard: !!i.json.isBonusCard
}));
const firstDraw = $('Draw Cards').first().json;
const last = $('Finalize').first().json;
return [{
  json: {
    cards,
    batchId: last.batchId,
    pack: { shiny: !!firstDraw.isShinyPack, bonusCard: cards.some((c) => c.isBonusCard) },
    pity: { pullsSinceTop: last.pullsSinceTop },
    booster: { extensionId: last.extensionId, count: last.boosterCount },
    xp: { total: last.xp, level: levelForXp(last.xp), leveledUp: (last.levelsGained || 0) > 0 }
  }
}];

const cards = $('Draw Cards').all().map((i) => ({
  cardId: i.json.cardId,
  name: i.json.name,
  artist: i.json.artist,
  description: i.json.description,
  imageId: i.json.imageId,
  rarity: i.json.rarity,
  isFirstEver: !!i.json.isFirstEver,
  serialNumber: i.json.serialNumber
}));
const draw = $('Draw Cards').first().json;
return [{ json: { cards, dryRun: true, pity: { pullsSinceTop: draw.pullsSinceTop }, booster: { extensionId: draw.extensionId, count: draw.newBoosterCount } } }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
function toDateStr(v) { if (v == null) return null; if (typeof v === 'number') return new Date(v * 1000).toISOString().slice(0, 10); return String(v).slice(0, 10); }
const docId = $('Set Config').first().json.docId;
const userId = $('Finalize').first().json.userId;
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(new Date());
const rows = $('Quest OpenBooster: Get Daily Quests').all().map((i) => i.json).filter((r) => r.id != null);
const row = rows.find((r) => refId(r.User) === userId && toDateStr(r.Date) === today);

const flags = { LoginDone: false, CraftDone: false, TradeDone: false, OpenBoosterDone: false, RewardClaimed: false };
if (row) {
  flags.LoginDone = !!row.LoginDone;
  flags.CraftDone = !!row.CraftDone;
  flags.TradeDone = !!row.TradeDone;
  flags.OpenBoosterDone = !!row.OpenBoosterDone;
  flags.RewardClaimed = !!row.RewardClaimed;
}
flags.OpenBoosterDone = true;

const completedCount = ["LoginDone","CraftDone","TradeDone","OpenBoosterDone"].filter((k) => flags[k]).length;
const shouldGrantReward = completedCount >= 2 && !flags.RewardClaimed;
if (shouldGrantReward) flags.RewardClaimed = true;

return [{ json: { docId, userId, today, rowId: row ? row.id : null, exists: !!row, shouldGrantReward, ...flags } }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
function toDateStr(v) { if (v == null) return null; if (typeof v === 'number') return new Date(v * 1000).toISOString().slice(0, 10); return String(v).slice(0, 10); }
function mondayOf(dateStr) {
  const d = new Date(dateStr + 'T00:00:00Z');
  const day = d.getUTCDay();
  const diff = day === 0 ? 6 : day - 1;
  d.setUTCDate(d.getUTCDate() - diff);
  return d.toISOString().slice(0, 10);
}
const docId = $('Set Config').first().json.docId;
const userId = $('Finalize').first().json.userId;
const todayParis = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(new Date());
const weekStart = mondayOf(todayParis);
const TARGET = 5;
const rows = $('Quest Weekly OpenBooster: Get Weekly Quests').all().map((i) => i.json).filter((r) => r.id != null);
const row = rows.find((r) => refId(r.User) === userId && toDateStr(r.WeekStart) === weekStart);

const counts = { LoginCount: 0, CraftCount: 0, TradeCount: 0, OpenBoosterCount: 0 };
let lastLoginCountedDate = null;
let rewardClaimed = false;
if (row) {
  counts.LoginCount = row.LoginCount || 0;
  counts.CraftCount = row.CraftCount || 0;
  counts.TradeCount = row.TradeCount || 0;
  counts.OpenBoosterCount = row.OpenBoosterCount || 0;
  lastLoginCountedDate = row.LastLoginCountedDate || null;
  rewardClaimed = !!row.RewardClaimed;
}
counts.OpenBoosterCount += 1;

const completedCount = Object.values(counts).filter((c) => c >= TARGET).length;
const shouldGrantReward = completedCount >= 3 && !rewardClaimed;
if (shouldGrantReward) rewardClaimed = true;

return [{ json: { docId, userId, weekStart, rowId: row ? row.id : null, exists: !!row, shouldGrantReward, rewardClaimed, lastLoginCountedDate, ...counts } }];
